interface.definition:
#"SYSTEM_SYSRULES_headerContentLayout"(
  contents: {
    #"SYSTEM_SYSRULES_columnsLayout"(
      columns: {
        #"SYSTEM_SYSRULES_columnLayout"(
          contents: {
            #"SYSTEM_SYSRULES_sectionLayout_v1"(
              label: "Detalles",
              contents: {
                #"SYSTEM_SYSRULES_cardLayout"(
                  contents: {
                    #"SYSTEM_SYSRULES_columnsLayout"(
                      columns: {
                        #"SYSTEM_SYSRULES_columnLayout"(
                          contents: {
                            #"SYSTEM_SYSRULES_richTextDisplayField"(
                              label: "Código",
                              value: {
                                a!defaultValue(
                                  ri!record[#"urn:appian:record-field:v1:fb451186-de5a-46b7-9b2c-9966bbf8a357/2e186123-398d-4029-8cd2-622b9f271f71"],
                                  "–"
                                )
                              }
                            )
                          }
                        )
                      }
                    )
                  },
                  padding: "STANDARD",
                  shape: "SEMI_ROUNDED"
                )
              },
              marginBelow: "MORE",
              labelSize: "MEDIUM",
              labelColor: "STANDARD"
            )
          },
          width: "AUTO"
        )
      },
      stackWhen: {
        "TABLET_PORTRAIT",
        "PHONE"
      },
      marginAbove: if(
        #"SYSTEM_SYSRULES_isNativeMobile"(),
        "NONE",
        if(
          #"SYSTEM_SYSRULES_isPageWidth"({ "DESKTOP", "DESKTOP_WIDE" }),
          "MORE",
          "STANDARD"
        )
      ),
      spacing: "SPARSE"
    )
  },
  backgroundColor: "#fbfbfb"
)

